import type { User, UserData, Book, AuthorProfile, Highlight, Message } from '@/types';

const STORAGE_KEY = 'reading_platform_data';

function getStorageKey(userId: string): string {
  return `${STORAGE_KEY}_${userId}`;
}

export function createUser(username: string, displayName: string): User {
  const user: User = {
    id: `user_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    username,
    displayName,
    createdAt: Date.now(),
  };

  const userData: UserData = {
    user,
    books: [],
    authorProfiles: [],
    highlights: [],
    conversations: {},
  };

  saveUserData(userData);
  saveCurrentUserId(user.id);

  return user;
}

export function getCurrentUser(): User | null {
  const userId = localStorage.getItem('current_user_id');
  if (!userId) return null;

  const data = loadUserData(userId);
  return data?.user || null;
}

export function getCurrentUserData(): UserData | null {
  const userId = localStorage.getItem('current_user_id');
  if (!userId) return null;

  return loadUserData(userId);
}

export function saveUserData(userData: UserData): void {
  const key = getStorageKey(userData.user.id);
  try {
    localStorage.setItem(key, JSON.stringify(userData));
  } catch (e) {
    console.error('Failed to save user data:', e);
  }
}

export function loadUserData(userId: string): UserData | null {
  const key = getStorageKey(userId);
  try {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : null;
  } catch (e) {
    console.error('Failed to load user data:', e);
    return null;
  }
}

export function saveCurrentUserId(userId: string): void {
  localStorage.setItem('current_user_id', userId);
}

export function logout(): void {
  localStorage.removeItem('current_user_id');
}

export function addBookToUser(userId: string, book: Book, authorProfile: AuthorProfile): void {
  const data = loadUserData(userId);
  if (!data) return;

  const existingBookIndex = data.books.findIndex((b) => b.id === book.id);
  if (existingBookIndex >= 0) {
    data.books[existingBookIndex] = book;
  } else {
    data.books.push(book);
  }

  const existingProfileIndex = data.authorProfiles.findIndex(
    (p) => p.id === authorProfile.id
  );
  if (existingProfileIndex >= 0) {
    data.authorProfiles[existingProfileIndex] = authorProfile;
  } else {
    data.authorProfiles.push(authorProfile);
  }

  data.lastReadBookId = book.id;
  saveUserData(data);
}

export function removeBookFromUser(userId: string, bookId: string): void {
  const data = loadUserData(userId);
  if (!data) return;

  data.books = data.books.filter((b) => b.id !== bookId);
  data.authorProfiles = data.authorProfiles.filter((p) => {
    const book = data.books.find((b) => b.authorId === p.id);
    return !!book;
  });
  delete data.conversations[bookId];
  data.highlights = data.highlights.filter((h) => h.bookId !== bookId);

  if (data.lastReadBookId === bookId) {
    data.lastReadBookId = data.books[0]?.id;
  }

  saveUserData(data);
}

export function addHighlight(userId: string, highlight: Highlight): void {
  const data = loadUserData(userId);
  if (!data) return;

  data.highlights.push(highlight);
  saveUserData(data);
}

export function removeHighlight(userId: string, highlightId: string): void {
  const data = loadUserData(userId);
  if (!data) return;

  data.highlights = data.highlights.filter((h) => h.id !== highlightId);
  saveUserData(data);
}

export function getHighlights(userId: string, bookId?: string): Highlight[] {
  const data = loadUserData(userId);
  if (!data) return [];

  if (bookId) {
    return data.highlights.filter((h) => h.bookId === bookId);
  }
  return data.highlights;
}

export function saveConversation(userId: string, bookId: string, messages: Message[]): void {
  const data = loadUserData(userId);
  if (!data) return;

  data.conversations[bookId] = messages;
  saveUserData(data);
}

export function getConversation(userId: string, bookId: string): Message[] {
  const data = loadUserData(userId);
  if (!data) return [];

  return data.conversations[bookId] || [];
}

export function setLastReadBook(userId: string, bookId: string): void {
  const data = loadUserData(userId);
  if (!data) return;

  data.lastReadBookId = bookId;
  saveUserData(data);
}

export function getAllUsers(): User[] {
  const users: User[] = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key?.startsWith(STORAGE_KEY)) {
      try {
        const data = JSON.parse(localStorage.getItem(key) || '{}');
        if (data.user) {
          users.push(data.user);
        }
      } catch {
        // ignore
      }
    }
  }
  return users;
}

export function switchUser(userId: string): boolean {
  const data = loadUserData(userId);
  if (!data) return false;

  saveCurrentUserId(userId);
  return true;
}
