import { useState } from 'react';
import { ChevronLeft, ChevronRight, BookOpen, User, ArrowLeft } from 'lucide-react';
import type { Chapter } from '@/types';

interface SidebarProps {
  chapters: Chapter[];
  currentChapterId: string;
  onChapterSelect: (chapter: Chapter) => void;
  authorName: string;
  bookTitle: string;
  onBack?: () => void;
}

export function Sidebar({
  chapters,
  currentChapterId,
  onChapterSelect,
  authorName,
  bookTitle,
  onBack,
}: SidebarProps) {
  const [collapsed, setCollapsed] = useState(false);

  return (
    <div
      className={`relative flex flex-col bg-[var(--bg-secondary)] border-r border-[var(--border)] transition-all duration-300 ${
        collapsed ? 'w-12' : 'w-72'
      }`}
    >
      <button
        onClick={() => setCollapsed(!collapsed)}
        className="absolute -right-3 top-4 w-6 h-6 bg-[var(--accent)] rounded-full flex items-center justify-center text-[var(--bg-primary)] hover:bg-[var(--accent-hover)] transition-colors z-10"
      >
        {collapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
      </button>

      {!collapsed && (
        <>
          <div className="p-4 border-b border-[var(--border)]">
            {onBack && (
              <button
                onClick={onBack}
                className="flex items-center gap-1.5 text-xs text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors mb-3"
              >
                <ArrowLeft size={14} />
                <span>返回书架</span>
              </button>
            )}
            <div className="flex items-center gap-2 mb-2">
              <BookOpen size={18} className="text-[var(--accent)]" />
              <span className="text-sm font-medium text-[var(--text-secondary)]">
                阅读中
              </span>
            </div>
            <h2 className="text-base font-semibold text-[var(--text-primary)] leading-tight">
              {bookTitle}
            </h2>
            <div className="flex items-center gap-1 mt-1 text-sm text-[var(--text-muted)]">
              <User size={14} />
              <span>{authorName}</span>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto scrollbar-thin p-3">
            <h3 className="text-xs font-medium text-[var(--text-muted)] uppercase tracking-wider mb-2 px-2">
              目录
            </h3>
            <nav className="space-y-1">
              {chapters.map((chapter) => (
                <button
                  key={chapter.id}
                  onClick={() => onChapterSelect(chapter)}
                  className={`w-full text-left px-3 py-2 rounded-lg text-sm transition-all duration-200 sidebar-item ${
                    currentChapterId === chapter.id
                      ? 'active bg-[var(--bg-tertiary)]'
                      : 'text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] hover:text-[var(--text-primary)]'
                  }`}
                  style={{ paddingLeft: `${chapter.level * 12 + 12}px` }}
                >
                  <span className="line-clamp-2">{chapter.title}</span>
                </button>
              ))}
            </nav>
          </div>
        </>
      )}

      {collapsed && (
        <div className="flex flex-col items-center py-4 gap-4">
          <BookOpen size={20} className="text-[var(--accent)]" />
          <div className="w-6 h-px bg-[var(--border)]" />
          <span className="text-xs text-[var(--text-muted)] [writing-mode:vertical-lr]">
            {bookTitle.slice(0, 10)}
          </span>
        </div>
      )}
    </div>
  );
}
