export interface SearchResult {
  title: string;
  snippet: string;
  url: string;
}

function stringifyValue(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'object' && value !== null) {
    const entries = Object.entries(value);
    if (entries.length === 0) return '';
    return entries
      .map(([key, val]) => {
        if (typeof val === 'string') {
          return `${key}：${val}`;
        }
        if (Array.isArray(val)) {
          return `${key}：\n${val.map((v) => (typeof v === 'string' ? `- ${v}` : `- ${JSON.stringify(v)}`)).join('\n')}`;
        }
        return `${key}：${JSON.stringify(val)}`;
      })
      .join('\n\n');
  }
  return String(value || '');
}

async function callKimiAPI(
  prompt: string,
  apiKey: string,
  maxTokens: number = 4000
): Promise<string> {
  const response = await fetch('https://api.moonshot.cn/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: 'moonshot-v1-8k',
      messages: [
        {
          role: 'system',
          content: '你是一个专业的文学研究者，擅长分析作家的生平、性格和写作风格。',
        },
        { role: 'user', content: prompt },
      ],
      temperature: 0.7,
      max_tokens: maxTokens,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    console.error('[AI] API error:', response.status, errorText);
    throw new Error(`API request failed: ${response.status}`);
  }

  const data = await response.json();
  return data.choices[0]?.message?.content || '';
}

export async function enrichAuthorProfile(
  authorName: string,
  bookTitle: string,
  description: string,
  sampleContent: string,
  apiKey: string
): Promise<{
  biography: string;
  personality: string;
  writingStyle: string;
  keyConcepts: string[];
  timeline: Array<{ year: string; event: string; significance: string }>;
  works: Array<{ title: string; year: string; description: string; type: 'book' | 'essay' | 'speech' }>;
}> {
  console.log('[AI] Starting author profile generation for:', authorName);

  // Try detailed prompt first
  let content = '';
  let usedFallback = false;

  try {
    const detailedPrompt = `请为作者"${authorName}"生成详细的数字人档案。这位作者写了《${bookTitle}》。

${description ? `书籍简介：${description}\n\n` : ''}

【书籍原文样本】（请分析这些原文，提取作者的文风和语言特点）：
"""
${sampleContent.slice(0, 2000)}
"""

请按以下JSON格式返回详细内容：

{
  "biography": "详细的生平介绍，300-500字。包含：出生背景、教育经历、职业生涯、写作动机、学术成就等。",
  "personality": "详细的性格分析，300-500字。包含：性格特点、说话方式、价值观、思维方式等。",
  "writingStyle": "详细的写作风格分析，300-500字。基于原文样本分析：文风特点、论证方式、语言特色、结构特点等。",
  "keyConcepts": ["核心概念1", "核心概念2", ...],
  "timeline": [
    {"year": "年份", "event": "重要事件", "significance": "影响"}
  ],
  "works": [
    {"title": "著作名", "year": "年份", "description": "简介", "type": "book"}
  ]
}

要求：
1. 所有文本字段必须是纯文本字符串
2. 内容要详细，每个字段300-500字
3. writingStyle必须基于原文样本分析
4. keyConcepts列出8-12个
5. timeline列出4-6个
6. works列出3-5部
7. 全部用中文
8. 只返回JSON`;

    console.log('[AI] Trying detailed prompt...');
    content = await callKimiAPI(detailedPrompt, apiKey, 4000);
    console.log('[AI] Detailed prompt succeeded');
  } catch (error) {
    console.warn('[AI] Detailed prompt failed, trying fallback:', error);

    // Fallback: simpler prompt without book content
    try {
      const fallbackPrompt = `请为作者"${authorName}"生成数字人档案。这位作者写了《${bookTitle}》。

请按JSON格式返回：
{
  "biography": "作者生平介绍，200-400字",
  "personality": "作者性格特点和说话风格，200-400字",
  "writingStyle": "作者写作风格分析，200-400字",
  "keyConcepts": ["概念1", "概念2"],
  "timeline": [{"year": "年份", "event": "事件", "significance": "影响"}],
  "works": [{"title": "书名", "year": "年份", "description": "简介", "type": "book"}]
}

要求：纯文本字符串，中文，只返回JSON`;

      content = await callKimiAPI(fallbackPrompt, apiKey, 3000);
      usedFallback = true;
      console.log('[AI] Fallback prompt succeeded');
    } catch (fallbackError) {
      console.error('[AI] Fallback also failed:', fallbackError);
      throw fallbackError;
    }
  }

  console.log('[AI] Response content length:', content.length);
  console.log('[AI] Used fallback:', usedFallback);

  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    console.error('[AI] No JSON found in response');
    throw new Error('No JSON found in response');
  }

  let parsed;
  try {
    parsed = JSON.parse(jsonMatch[0]);
  } catch (e) {
    console.error('[AI] JSON parse error:', e);
    throw e;
  }

  console.log('[AI] Parsed fields:', Object.keys(parsed));

  const result = {
    biography: stringifyValue(parsed.biography) || `${authorName}是一位作家，著有《${bookTitle}》。`,
    personality: stringifyValue(parsed.personality),
    writingStyle: stringifyValue(parsed.writingStyle),
    keyConcepts: Array.isArray(parsed.keyConcepts) ? parsed.keyConcepts.filter((c: unknown) => typeof c === 'string') : [],
    timeline: Array.isArray(parsed.timeline) ? parsed.timeline.filter((t: unknown) => t && typeof t === 'object').map((t: Record<string, unknown>) => ({
      year: String(t.year || ''),
      event: String(t.event || ''),
      significance: String(t.significance || ''),
    })) : [],
    works: Array.isArray(parsed.works) ? parsed.works.filter((w: unknown) => w && typeof w === 'object').map((w: Record<string, unknown>) => ({
      title: String(w.title || ''),
      year: String(w.year || ''),
      description: String(w.description || ''),
      type: (w.type === 'essay' || w.type === 'speech' ? w.type : 'book') as 'book' | 'essay' | 'speech',
    })) : [],
  };

  console.log('[AI] Final result biography length:', result.biography.length);
  console.log('[AI] Final result personality length:', result.personality.length);
  console.log('[AI] Final result writingStyle length:', result.writingStyle.length);

  return result;
}
