import { useRef, useCallback, useEffect, useState } from 'react';
import { useReaderStore } from '@/store/useReaderStore';
import { useUserStore } from '@/store/useUserStore';
import { Highlighter, MessageCircle, StickyNote } from 'lucide-react';
import type { Chapter } from '@/types';

interface TextContentProps {
  chapter: Chapter | undefined;
  bookId: string;
}

export function TextContent({ chapter, bookId }: TextContentProps) {
  const contentRef = useRef<HTMLDivElement>(null);
  const { setSelectedText, toggleChat } = useReaderStore();
  const { user, addHighlight, getHighlights } = useUserStore();
  const [showToolbar, setShowToolbar] = useState(false);
  const [toolbarPos, setToolbarPos] = useState({ x: 0, y: 0 });
  const [showNoteInput, setShowNoteInput] = useState(false);
  const [noteText, setNoteText] = useState('');
  const [highlights, setHighlights] = useState<Array<{ id: string; text: string; note?: string }>>([]);

  // Load highlights for this book
  useEffect(() => {
    if (user && bookId) {
      const bookHighlights = getHighlights(bookId);
      setHighlights(bookHighlights.map((h) => ({ id: h.id, text: h.text, note: h.note })));
    }
  }, [user, bookId, getHighlights]);

  const handleTextSelection = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) {
      setShowToolbar(false);
      setShowNoteInput(false);
      return;
    }

    const text = selection.toString().trim();
    if (text.length < 2) {
      setShowToolbar(false);
      setShowNoteInput(false);
      return;
    }

    setSelectedText(text);

    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    setToolbarPos({
      x: rect.left + rect.width / 2,
      y: rect.top - 50,
    });
    setShowToolbar(true);
    setShowNoteInput(false);
  }, [setSelectedText]);

  const handleHighlight = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) return;

    const text = selection.toString().trim();
    if (text.length < 2) return;

    if (user) {
      const highlight = {
        id: `hl_${Date.now()}`,
        bookId,
        chapterId: chapter?.id || '',
        text,
        color: 'yellow' as const,
        createdAt: Date.now(),
      };

      addHighlight(highlight);
      setHighlights((prev) => [...prev, { id: highlight.id, text }]);
    }

    selection.removeAllRanges();
    setShowToolbar(false);
  }, [chapter?.id, bookId, user, addHighlight]);

  const handleAddNote = useCallback(() => {
    setShowNoteInput(true);
  }, []);

  const handleSaveNote = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) return;

    const text = selection.toString().trim();
    if (text.length < 2) return;

    if (user) {
      const highlight = {
        id: `hl_${Date.now()}`,
        bookId,
        chapterId: chapter?.id || '',
        text,
        color: 'yellow' as const,
        note: noteText,
        createdAt: Date.now(),
      };

      addHighlight(highlight);
      setHighlights((prev) => [...prev, { id: highlight.id, text, note: noteText }]);
    }

    setNoteText('');
    setShowNoteInput(false);
    selection.removeAllRanges();
    setShowToolbar(false);
  }, [chapter?.id, bookId, user, addHighlight, noteText]);

  const handleChat = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) return;

    const text = selection.toString().trim();
    if (text.length < 2) return;

    setSelectedText(text);
    toggleChat(true);
    selection.removeAllRanges();
    setShowToolbar(false);
    setShowNoteInput(false);
  }, [setSelectedText, toggleChat]);

  useEffect(() => {
    const handleMouseUp = () => {
      handleTextSelection();
    };

    document.addEventListener('mouseup', handleMouseUp);
    return () => document.removeEventListener('mouseup', handleMouseUp);
  }, [handleTextSelection]);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (!target.closest('.selection-toolbar') && !target.closest('.note-input')) {
        const selection = window.getSelection();
        if (selection && selection.isCollapsed) {
          setShowToolbar(false);
          setShowNoteInput(false);
        }
      }
    };

    document.addEventListener('click', handleClick);
    return () => document.removeEventListener('click', handleClick);
  }, []);

  const renderContent = () => {
    if (!chapter) return null;

    const lines = chapter.content.split('\n');
    return lines.map((line, index) => {
      const trimmedLine = line.trim();
      if (!trimmedLine) {
        return <div key={index} className="h-4" />;
      }

      const isHeading =
        trimmedLine.length < 30 &&
        !trimmedLine.includes('。') &&
        !trimmedLine.includes('，') &&
        !trimmedLine.includes('、');

      if (isHeading) {
        return (
          <h2
            key={index}
            className="chapter-title text-xl text-[var(--text-primary)] mt-8 mb-4"
          >
            {trimmedLine}
          </h2>
        );
      }

      return (
        <p
          key={index}
          className="reader-text text-[var(--text-secondary)] mb-4 text-base"
        >
          {trimmedLine}
        </p>
      );
    });
  };

  if (!chapter) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <p className="text-[var(--text-muted)]">请选择章节</p>
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto relative">
      <div ref={contentRef} className="max-w-3xl mx-auto px-8 py-10">
        <h1 className="chapter-title text-2xl text-[var(--text-primary)] mb-8">
          {chapter.title}
        </h1>
        <div className="select-text">{renderContent()}</div>

        {/* Highlights display */}
        {highlights.length > 0 && (
          <div className="mt-8 pt-6 border-t border-[var(--border)]">
            <h3 className="text-sm font-semibold text-[var(--text-muted)] mb-3">
              我的笔记 ({highlights.length})
            </h3>
            <div className="space-y-2">
              {highlights.map((hl) => (
                <div
                  key={hl.id}
                  className="p-3 bg-yellow-500/10 border-l-2 border-yellow-500/50 rounded-r-lg"
                >
                  <p className="text-sm text-[var(--text-secondary)]">{hl.text}</p>
                  {hl.note && (
                    <p className="text-xs text-[var(--text-muted)] mt-1 italic">
                      笔记: {hl.note}
                    </p>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Selection Toolbar */}
      {showToolbar && !showNoteInput && (
        <div
          className="selection-toolbar fixed z-50 flex items-center gap-1 bg-[var(--bg-secondary)] border border-[var(--border)] rounded-lg shadow-lg px-2 py-1.5"
          style={{
            left: `${toolbarPos.x}px`,
            top: `${toolbarPos.y}px`,
            transform: 'translateX(-50%)',
          }}
        >
          <button
            onClick={handleHighlight}
            className="p-1.5 text-[var(--text-muted)] hover:text-[var(--accent)] hover:bg-[var(--bg-tertiary)] rounded transition-colors"
            title="画线"
          >
            <Highlighter size={16} />
          </button>
          <button
            onClick={handleAddNote}
            className="p-1.5 text-[var(--text-muted)] hover:text-[var(--accent)] hover:bg-[var(--bg-tertiary)] rounded transition-colors"
            title="添加笔记"
          >
            <StickyNote size={16} />
          </button>
          <button
            onClick={handleChat}
            className="p-1.5 text-[var(--text-muted)] hover:text-[var(--accent)] hover:bg-[var(--bg-tertiary)] rounded transition-colors"
            title="与作者对话"
          >
            <MessageCircle size={16} />
          </button>
        </div>
      )}

      {/* Note Input */}
      {showNoteInput && (
        <div
          className="note-input fixed z-50 bg-[var(--bg-secondary)] border border-[var(--border)] rounded-lg shadow-lg p-3 w-72"
          style={{
            left: `${toolbarPos.x}px`,
            top: `${toolbarPos.y}px`,
            transform: 'translateX(-50%)',
          }}
        >
          <textarea
            value={noteText}
            onChange={(e) => setNoteText(e.target.value)}
            placeholder="添加笔记..."
            className="w-full bg-[var(--bg-tertiary)] text-[var(--text-primary)] placeholder:text-[var(--text-muted)] px-3 py-2 rounded-lg text-sm outline-none resize-none h-20"
            autoFocus
          />
          <div className="flex justify-end gap-2 mt-2">
            <button
              onClick={() => {
                setShowNoteInput(false);
                setNoteText('');
              }}
              className="px-3 py-1 text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleSaveNote}
              className="px-3 py-1 text-xs bg-[var(--accent)] text-[var(--bg-primary)] rounded-lg hover:bg-[var(--accent-hover)] transition-colors"
            >
              保存
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
