import { useState } from 'react';
import type { AuthorProfile } from '@/types';
import { User, BookOpen, Calendar, Lightbulb, X } from 'lucide-react';

interface AuthorProfileProps {
  isOpen: boolean;
  onClose: () => void;
  profile: AuthorProfile;
}

// Safely convert any value to string for rendering
function safeString(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'object' && value !== null) {
    const entries = Object.entries(value);
    if (entries.length === 0) return '';
    return entries
      .map(([key, val]) => {
        if (typeof val === 'string') {
          return `${key}：${val}`;
        }
        if (Array.isArray(val)) {
          return `${key}：\n${val.map((v) => (typeof v === 'string' ? `- ${v}` : `- ${JSON.stringify(v)}`)).join('\n')}`;
        }
        return `${key}：${JSON.stringify(val)}`;
      })
      .join('\n\n');
  }
  return String(value || '');
}

export function AuthorProfilePanel({ isOpen, onClose, profile }: AuthorProfileProps) {
  const [activeTab, setActiveTab] = useState<'biography' | 'works' | 'timeline'>('biography');

  if (!isOpen) return null;

  // Ensure all text fields are strings
  const safeProfile = {
    ...profile,
    biography: safeString(profile.biography),
    personality: safeString(profile.personality),
    writingStyle: safeString(profile.writingStyle),
    keyConcepts: Array.isArray(profile.keyConcepts)
      ? profile.keyConcepts.filter((c): c is string => typeof c === 'string')
      : [],
    timeline: Array.isArray(profile.timeline) ? profile.timeline : [],
    works: Array.isArray(profile.works) ? profile.works : [],
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <div className="bg-[var(--bg-secondary)] rounded-2xl w-full max-w-2xl max-h-[80vh] overflow-hidden shadow-2xl border border-[var(--border)] mx-4">
        <div className="flex items-center justify-between p-6 border-b border-[var(--border)]">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 rounded-full bg-[var(--accent)] flex items-center justify-center">
              <User size={28} className="text-[var(--bg-primary)]" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-[var(--text-primary)]">{safeProfile.name}</h2>
              <p className="text-sm text-[var(--text-muted)]">
                {safeProfile.birthDate || ''} {safeProfile.deathDate ? `- ${safeProfile.deathDate}` : safeProfile.birthDate ? '' : ''}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <div className="flex border-b border-[var(--border)]">
          {[
            { id: 'biography' as const, label: '生平', icon: User },
            { id: 'works' as const, label: '著作', icon: BookOpen },
            { id: 'timeline' as const, label: '年表', icon: Calendar },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-1 flex items-center justify-center gap-2 py-3 text-sm font-medium transition-colors ${
                activeTab === tab.id
                  ? 'text-[var(--accent)] border-b-2 border-[var(--accent)]'
                  : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
              }`}
            >
              <tab.icon size={16} />
              {tab.label}
            </button>
          ))}
        </div>

        <div className="overflow-y-auto scrollbar-thin p-6 max-h-[50vh]">
          {activeTab === 'biography' && (
            <div className="space-y-4">
              {safeProfile.personality && (
                <div className="bg-[var(--bg-tertiary)] rounded-lg p-4">
                  <h3 className="text-sm font-semibold text-[var(--accent)] mb-2 flex items-center gap-2">
                    <Lightbulb size={16} />
                    性格特点
                  </h3>
                  <p className="text-sm text-[var(--text-secondary)] leading-relaxed whitespace-pre-line">
                    {safeProfile.personality}
                  </p>
                </div>
              )}
              {safeProfile.writingStyle && (
                <div className="bg-[var(--bg-tertiary)] rounded-lg p-4">
                  <h3 className="text-sm font-semibold text-[var(--accent)] mb-2 flex items-center gap-2">
                    <BookOpen size={16} />
                    语言风格
                  </h3>
                  <p className="text-sm text-[var(--text-secondary)] leading-relaxed whitespace-pre-line">
                    {safeProfile.writingStyle}
                  </p>
                </div>
              )}
              {safeProfile.biography && (
                <div>
                  <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-2">生平简介</h3>
                  <p className="text-sm text-[var(--text-secondary)] leading-relaxed whitespace-pre-line">
                    {safeProfile.biography}
                  </p>
                </div>
              )}
              {safeProfile.keyConcepts.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {safeProfile.keyConcepts.map((concept) => (
                    <span
                      key={concept}
                      className="px-3 py-1 bg-[var(--accent)]/10 text-[var(--accent)] rounded-full text-xs font-medium"
                    >
                      {concept}
                    </span>
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'works' && (
            <div className="space-y-3">
              {safeProfile.works.length > 0 ? (
                safeProfile.works.map((work, index) => (
                  <div
                    key={index}
                    className="flex items-start gap-3 p-3 bg-[var(--bg-tertiary)] rounded-lg"
                  >
                    <BookOpen size={18} className="text-[var(--accent)] flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <h4 className="text-sm font-medium text-[var(--text-primary)]">
                          {String(work.title || '')}
                        </h4>
                        <span className="text-xs text-[var(--text-muted)]">{String(work.year || '')}</span>
                      </div>
                      <p className="text-xs text-[var(--text-secondary)] mt-1">
                        {String(work.description || '')}
                      </p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-sm text-[var(--text-muted)] text-center py-8">
                  暂无著作信息
                </p>
              )}
            </div>
          )}

          {activeTab === 'timeline' && (
            <div className="space-y-0">
              {safeProfile.timeline.length > 0 ? (
                safeProfile.timeline.map((event, index) => (
                  <div key={index} className="flex gap-4">
                    <div className="flex flex-col items-center">
                      <div className="w-3 h-3 rounded-full bg-[var(--accent)]" />
                      {index < safeProfile.timeline.length - 1 && (
                        <div className="w-px h-full bg-[var(--border)]" />
                      )}
                    </div>
                    <div className="pb-6">
                      <span className="text-sm font-semibold text-[var(--accent)]">
                        {String(event.year || '')}
                      </span>
                      <h4 className="text-sm font-medium text-[var(--text-primary)] mt-1">
                        {String(event.event || '')}
                      </h4>
                      <p className="text-xs text-[var(--text-secondary)] mt-1">
                        {String(event.significance || '')}
                      </p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-sm text-[var(--text-muted)] text-center py-8">
                  暂无详细年表信息
                </p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
