import { getAuthorProfile } from '@/data/booksRegistry';
import type { AuthorProfile } from '@/types';

interface ChatRequest {
  message: string;
  selectedText: string;
  chapterTitle: string;
  bookTitle: string;
  authorName: string;
  bookId: string;
  history: Array<{ role: string; content: string }>;
}

export async function sendMessageToAI(request: ChatRequest): Promise<string> {
  const kimiApiKey = import.meta.env.VITE_KIMI_API_KEY;
  const openaiApiKey = import.meta.env.VITE_OPENAI_API_KEY;

  if (kimiApiKey) {
    try {
      return await sendToKimi(request, kimiApiKey);
    } catch (error) {
      console.error('Kimi API error:', error);
    }
  }

  if (openaiApiKey) {
    try {
      return await sendToOpenAI(request, openaiApiKey);
    } catch (error) {
      console.error('OpenAI API error:', error);
    }
  }

  return generateLocalResponse(request);
}

async function sendToKimi(request: ChatRequest, apiKey: string): Promise<string> {
  const systemPrompt = buildSystemPrompt(request);

  const messages = [
    { role: 'system', content: systemPrompt },
    ...request.history.slice(-6).map((h) => ({ role: h.role, content: h.content })),
    { role: 'user', content: request.message },
  ];

  const response = await fetch('https://api.moonshot.cn/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: 'moonshot-v1-8k',
      messages,
      temperature: 0.7,
      max_tokens: 1000,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    console.error('Kimi API error response:', errorText);
    throw new Error(`Kimi API request failed: ${response.status}`);
  }

  const data = await response.json();
  return data.choices[0]?.message?.content || '抱歉，我没有理解你的问题。';
}

async function sendToOpenAI(request: ChatRequest, apiKey: string): Promise<string> {
  const systemPrompt = buildSystemPrompt(request);

  const messages = [
    { role: 'system', content: systemPrompt },
    ...request.history.slice(-6).map((h) => ({ role: h.role, content: h.content })),
    { role: 'user', content: request.message },
  ];

  const response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: 'gpt-4',
      messages,
      temperature: 0.7,
      max_tokens: 1000,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    console.error('OpenAI API error response:', errorText);
    throw new Error(`OpenAI API request failed: ${response.status}`);
  }

  const data = await response.json();
  return data.choices[0]?.message?.content || '抱歉，我没有理解你的问题。';
}

function buildSystemPrompt(request: ChatRequest): string {
  const profile = getAuthorProfile(request.bookId);

  if (request.bookId === 'maoxuan-vol1') {
    return buildMaoZedongPrompt(request);
  }

  return buildGenericAuthorPrompt(request, profile);
}

