function generateLocalResponse(request: ChatRequest): string {
  const responses = [
    `这是一个很好的问题。关于「${request.selectedText.slice(0, 20)}...」这段内容，我当时写作时确实经过了深思熟虑。`,
    `你注意到了这段文字的关键之处。这反映了我一直以来的思考方式。`,
    `这个问题提得很好。让我从我的角度来谈谈这个问题。`,
    `你读得很仔细。这段文字的背后，有我更深层的考虑。`,
    `这是一个值得深入探讨的问题。我在写作时也曾反复思考过这一点。`,
  ];

  return responses[Math.floor(Math.random() * responses.length)];
}
