import { enrichAuthorProfile } from './webSearch';
import type { AuthorProfile, Chapter } from '@/types';

export async function generateAuthorProfile(
  authorName: string,
  bookTitle: string,
  description: string,
  chapters: Chapter[],
  apiKey?: string
): Promise<AuthorProfile> {
  const kimiApiKey = apiKey || import.meta.env.VITE_KIMI_API_KEY;

  if (kimiApiKey) {
    try {
      return await generateWithAI(authorName, bookTitle, description, chapters, kimiApiKey);
    } catch (error) {
      console.error('AI author generation failed:', error);
    }
  }

  return generateFallbackProfile(authorName, bookTitle);
}

async function generateWithAI(
  authorName: string,
  bookTitle: string,
  description: string,
  chapters: Chapter[],
  apiKey: string
): Promise<AuthorProfile> {
  // Extract sample content from chapters for style analysis
  const sampleContent = extractSampleContent(chapters);

  // Use the enriched profile generation from webSearch with book content
  const enriched = await enrichAuthorProfile(authorName, bookTitle, description, sampleContent, apiKey);

  return {
    id: '',
    name: authorName,
    biography: enriched.biography,
    personality: enriched.personality,
    writingStyle: enriched.writingStyle,
    keyConcepts: enriched.keyConcepts,
    timeline: enriched.timeline,
    works: enriched.works,
  };
}

function extractSampleContent(chapters: Chapter[]): string {
  // Extract samples from first few chapters to analyze writing style
  const samples: string[] = [];
  let totalLength = 0;
  const maxLength = 3000;

  for (const chapter of chapters.slice(0, 3)) {
    if (chapter.content) {
      const paragraphs = chapter.content.split('\n\n').filter((p) => p.trim().length > 50);
      for (const paragraph of paragraphs.slice(0, 3)) {
        if (totalLength + paragraph.length > maxLength) break;
        samples.push(paragraph.trim());
        totalLength += paragraph.length;
      }
    }
    if (totalLength >= maxLength) break;
  }

  return samples.join('\n\n');
}

function generateFallbackProfile(
  authorName: string,
  bookTitle: string
): AuthorProfile {
  return {
    id: '',
    name: authorName,
    biography: `${authorName}是一位作家，著有《${bookTitle}》。关于这位作者的详细信息，建议读者通过其他渠道进一步了解。`,
    personality: `性格特点：
- 理性、深思熟虑，善于分析问题
- 对知识充满热情，乐于与读者分享见解
- 说话风格：清晰、有条理、尊重读者
- 善于倾听，愿意深入探讨问题
- 对不同的观点持开放态度`,
    writingStyle: `文风特点：
- 语言清晰流畅，避免晦涩难懂
- 论证严谨，善用逻辑推理
- 善于举例说明，让抽象概念具体化
- 结构清晰，层次分明
- 引用丰富，知识面广`,
    keyConcepts: ['思想', '方法', '理论', '实践', '创新'],
    timeline: [],
    works: [
      {
        title: `《${bookTitle}》`,
        year: '近年',
        description: '代表作',
        type: 'book',
      },
    ],
  };
}
