import JSZip from 'jszip';
import type { Book, Chapter } from '@/types';

interface ParsedEpub {
  title: string;
  author: string;
  description: string;
  chapters: Chapter[];
}

export async function parseEpub(arrayBuffer: ArrayBuffer): Promise<ParsedEpub> {
  const zip = await JSZip.loadAsync(arrayBuffer);

  // Find container.xml to locate OPF file
  const containerXml = await zip.file('META-INF/container.xml')?.async('text');
  if (!containerXml) {
    throw new Error('Invalid EPUB: container.xml not found');
  }

  const opfPathMatch = containerXml.match(/full-path="([^"]+)"/);
  const opfPath = opfPathMatch ? opfPathMatch[1] : 'OEBPS/content.opf';
  const opfDir = opfPath.substring(0, opfPath.lastIndexOf('/') + 1) || '';

  const opfContent = await zip.file(opfPath)?.async('text');
  if (!opfContent) {
    throw new Error('Invalid EPUB: OPF file not found');
  }

  // Parse metadata
  const titleMatch = opfContent.match(/<dc:title[^>]*>([^<]+)<\/dc:title>/i);
  const authorMatch = opfContent.match(/<dc:creator[^>]*>([^<]+)<\/dc:creator>/i);
  const descMatch = opfContent.match(/<dc:description[^>]*>([^<]+)<\/dc:description>/i);

  const title = titleMatch ? titleMatch[1].trim() : '未知书名';
  const author = authorMatch ? authorMatch[1].trim() : '未知作者';
  const description = descMatch ? descMatch[1].trim() : '';

  // Parse spine (reading order)
  const spineMatch = opfContent.match(/<spine[^>]*>([\s\S]*?)<\/spine>/i);
  const itemrefMatches = spineMatch
    ? [...spineMatch[1].matchAll(/<itemref[^>]+idref="([^"]+)"/g)]
    : [];
  const idrefs = itemrefMatches.map((m) => m[1]);

  // Parse manifest (file mapping)
  const manifestMatch = opfContent.match(/<manifest[^>]*>([\s\S]*?)<\/manifest>/i);
  const itemMatches = manifestMatch
    ? [...manifestMatch[1].matchAll(/<item[^>]+id="([^"]+)"[^>]+href="([^"]+)"/g)]
    : [];

  const manifestMap = new Map<string, string>();
  itemMatches.forEach((m) => {
    manifestMap.set(m[1], opfDir + m[2]);
  });

  // Extract chapters
  const chapters: Chapter[] = [];
  let order = 1;

  for (const idref of idrefs) {
    const href = manifestMap.get(idref);
    if (!href) continue;

    const file = zip.file(href);
    if (!file) continue;

    const content = await file.async('text');

    // Parse HTML content
    const bodyMatch = content.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    const bodyContent = bodyMatch ? bodyMatch[1] : content;

    // Extract title from h1 or first heading
    const h1Match = bodyContent.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    const h2Match = bodyContent.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
    const chapterTitle = h1Match
      ? stripHtml(h1Match[1]).trim()
      : h2Match
        ? stripHtml(h2Match[1]).trim()
        : `第${order}章`;

    // Extract text content with paragraph structure preserved
    const textContent = extractTextWithParagraphs(bodyContent);

    if (textContent.length > 100) {
      chapters.push({
        id: `ch-${order}`,
        title: chapterTitle,
        level: 1,
        order,
        content: textContent,
      });
      order++;
    }
  }

  if (chapters.length === 0) {
    throw new Error('No readable chapters found in EPUB');
  }

  return { title, author, description, chapters };
}

export function parseTxt(text: string): ParsedEpub {
  const lines = text.split('\n').map((l) => l.trim());

  // Try to detect title and author from first few lines
  let title = '导入的书籍';
  let author = '未知作者';

  const titleMatch = text.match(/^书名[：:]\s*(.+)$/m);
  const authorMatch = text.match(/^作者[：:]\s*(.+)$/m);

  if (titleMatch) title = titleMatch[1].trim();
  if (authorMatch) author = authorMatch[1].trim();

  // Split into chapters based on common patterns
  const chapters: Chapter[] = [];
  let currentChapter: { title: string; lines: string[] } | null = null;
  let order = 1;

  const chapterPatterns = [
    /^第[一二三四五六七八九十百千零\d]+章[\s\S]*$/,
    /^Chapter\s+\d+/i,
    /^\d+\.\s+.+$/,
    /^[\s]*第[一二三四五六七八九十百千零\d]+[章节卷篇][\s]*$/,
  ];

  for (const line of lines) {
    if (!line) continue;

    const isChapterHeading = chapterPatterns.some((p) => p.test(line));

    if (isChapterHeading) {
      if (currentChapter && currentChapter.lines.length > 5) {
        chapters.push({
          id: `ch-${order}`,
          title: currentChapter.title,
          level: 1,
          order,
          content: currentChapter.lines.join('\n\n'),
        });
        order++;
      }
      currentChapter = { title: line.replace(/^[\s#]+/, '').trim(), lines: [] };
    } else if (currentChapter) {
      currentChapter.lines.push(line);
    }
  }

  // Add last chapter
  if (currentChapter && currentChapter.lines.length > 5) {
    chapters.push({
      id: `ch-${order}`,
      title: currentChapter.title,
      level: 1,
      order,
      content: currentChapter.lines.join('\n\n'),
    });
  }

  // If no chapters detected, treat entire text as one chapter
  if (chapters.length === 0) {
    const content = lines.filter((l) => l.length > 0).join('\n\n');
    if (content.length > 100) {
      chapters.push({
        id: 'ch-1',
        title: '全文',
        level: 1,
        order: 1,
        content,
      });
    }
  }

  return { title, author, description: '', chapters };
}

function extractTextWithParagraphs(html: string): string {
  // Remove script and style tags completely
  let text = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Replace block-level tags with paragraph markers
  // These tags indicate paragraph/section boundaries
  text = text
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<p[^>]*>/gi, '')
    .replace(/<\/div>/gi, '\n')
    .replace(/<div[^>]*>/gi, '')
    .replace(/<\/section>/gi, '\n\n')
    .replace(/<section[^>]*>/gi, '')
    .replace(/<\/article>/gi, '\n\n')
    .replace(/<article[^>]*>/gi, '')
    .replace(/<\/h[1-6]>/gi, '\n\n')
    .replace(/<h[1-6][^>]*>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/blockquote>/gi, '\n\n')
    .replace(/<blockquote[^>]*>/gi, '');

  // Remove remaining tags
  text = text.replace(/<[^>]+>/g, '');

  // Decode HTML entities
  text = text
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&mdash;/g, '——')
    .replace(/&ndash;/g, '–')
    .replace(/&hellip;/g, '…')
    .replace(/&ldquo;/g, '"')
    .replace(/&rdquo;/g, '"')
    .replace(/&lsquo;/g, "'")
    .replace(/&rsquo;/g, "'")
    .replace(/&emsp;/g, '  ')
    .replace(/&ensp;/g, ' ');

  // Clean up whitespace while preserving paragraph structure
  text = text
    .split('\n')
    .map((line) => line.trim())
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();

  return text;
}

function stripHtml(html: string): string {
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}
