import { Component, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error('ErrorBoundary caught:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-6">
          <div className="max-w-md w-full bg-[var(--bg-secondary)] border border-[var(--border)] rounded-2xl p-6">
            <h2 className="text-lg font-semibold text-red-400 mb-2">出错了</h2>
            <p className="text-sm text-[var(--text-secondary)] mb-4">
              应用遇到了一个错误。请尝试刷新页面。
            </p>
            <details className="mb-4">
              <summary className="text-xs text-[var(--text-muted)] cursor-pointer">
                错误详情
              </summary>
              <pre className="mt-2 p-3 bg-[var(--bg-tertiary)] rounded-lg text-xs text-red-400 overflow-auto">
                {this.state.error?.message}
                {'\n'}
                {this.state.error?.stack}
              </pre>
            </details>
            <button
              onClick={() => window.location.reload()}
              className="w-full py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] rounded-xl font-medium hover:bg-[var(--accent-hover)] transition-colors"
            >
              刷新页面
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}
