import { useState, useMemo } from 'react';
import { Search, X, FileText } from 'lucide-react';
import type { Chapter } from '@/types';

interface SearchPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onChapterSelect: (chapter: Chapter) => void;
  chapters: Chapter[];
}

export function SearchPanel({ isOpen, onClose, onChapterSelect, chapters }: SearchPanelProps) {
  const [query, setQuery] = useState('');

  const results = useMemo(() => {
    if (!query.trim() || query.length < 2) return [];

    const searchResults: Array<{
      chapter: Chapter;
      preview: string;
      matchIndex: number;
    }> = [];

    const lowerQuery = query.toLowerCase();

    chapters.forEach((chapter) => {
      const lowerContent = chapter.content.toLowerCase();
      let index = lowerContent.indexOf(lowerQuery);

      while (index !== -1) {
        const start = Math.max(0, index - 40);
        const end = Math.min(chapter.content.length, index + query.length + 40);
        const preview = chapter.content.slice(start, end);

        searchResults.push({
          chapter,
          preview: start > 0 ? `...${preview}...` : `${preview}...`,
          matchIndex: index,
        });

        index = lowerContent.indexOf(lowerQuery, index + 1);
      }
    });

    return searchResults.slice(0, 20);
  }, [query, chapters]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-20 bg-black/50 backdrop-blur-sm">
      <div className="bg-[var(--bg-secondary)] rounded-2xl w-full max-w-2xl max-h-[70vh] overflow-hidden shadow-2xl border border-[var(--border)] mx-4">
        <div className="p-4 border-b border-[var(--border)]">
          <div className="flex items-center gap-3">
            <Search size={20} className="text-[var(--text-muted)]" />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="搜索全书内容..."
              className="flex-1 bg-transparent text-[var(--text-primary)] placeholder:text-[var(--text-muted)] outline-none text-base"
              autoFocus
            />
            <button
              onClick={onClose}
              className="p-1.5 text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] rounded-lg transition-colors"
            >
              <X size={18} />
            </button>
          </div>
        </div>

        <div className="overflow-y-auto max-h-[50vh]">
          {results.length > 0 ? (
            <div className="divide-y divide-[var(--border)]">
              {results.map((result, index) => (
                <button
                  key={index}
                  onClick={() => {
                    onChapterSelect(result.chapter);
                    onClose();
                  }}
                  className="w-full text-left p-4 hover:bg-[var(--bg-tertiary)] transition-colors"
                >
                  <div className="flex items-center gap-2 mb-2">
                    <FileText size={14} className="text-[var(--accent)]" />
                    <span className="text-sm font-medium text-[var(--text-primary)]">
                      {result.chapter.title}
                    </span>
                  </div>
                  <p className="text-sm text-[var(--text-secondary)] line-clamp-2">
                    {result.preview}
                  </p>
                </button>
              ))}
            </div>
          ) : query.length >= 2 ? (
            <div className="p-8 text-center">
              <p className="text-sm text-[var(--text-muted)]">未找到相关内容</p>
            </div>
          ) : (
            <div className="p-8 text-center">
              <p className="text-sm text-[var(--text-muted)]">
                输入关键词搜索全书内容
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
