import { useState, useRef, useCallback, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useUserStore } from '@/store/useUserStore';
import { parseEpub, parseTxt } from '@/services/epubParser';
import { generateAuthorProfile } from '@/services/authorGenerator';
import { UserAuth } from '@/components/UserAuth';
import type { Book, AuthorProfile } from '@/types';
import {
  BookOpen,
  Upload,
  User,
  ChevronRight,
  FileText,
  X,
  Loader2,
  AlertCircle,
  Library,
  Trash2,
  Sparkles,
} from 'lucide-react';

export function BookshelfPage() {
  const navigate = useNavigate();
  const { user, userData, isLoading, isInitialized, init, addBook, removeBook } = useUserStore();
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState('');
  const [importProgress, setImportProgress] = useState('');
  const [enrichingAuthor, setEnrichingAuthor] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const hasInitRef = useRef(false);

  useEffect(() => {
    if (!hasInitRef.current && !isInitialized) {
      hasInitRef.current = true;
      init();
    }
  }, [init, isInitialized]);

  const books = userData?.books || [];

  const handleBookClick = (bookId: string) => {
    navigate(`/read/${bookId}`);
  };

  const handleDeleteBook = (e: React.MouseEvent, bookId: string) => {
    e.stopPropagation();
    if (window.confirm('确定要删除这本书吗？相关的对话记录和笔记也会被删除。')) {
      removeBook(bookId);
    }
  };

  const handleFileSelect = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setIsImporting(true);
      setImportError('');
      setImportProgress('正在解析文件...');

      try {
        let parsed;

        if (file.name.endsWith('.epub')) {
          const arrayBuffer = await file.arrayBuffer();
          parsed = await parseEpub(arrayBuffer);
        } else if (file.name.endsWith('.txt')) {
          const text = await file.text();
          parsed = parseTxt(text);
        } else {
          throw new Error('不支持的文件格式，请上传 .epub 或 .txt 文件');
        }

        console.log('[Import] Parsed book:', parsed.title, 'by', parsed.author);
        console.log('[Import] Chapters count:', parsed.chapters.length);

        setImportProgress('正在生成作者数字人...');

        const bookId = `book-${Date.now()}`;
        const authorId = `author-${Date.now()}`;
        const book: Book = {
          id: bookId,
          title: parsed.title,
          author: parsed.author,
          authorId: authorId,
          description: parsed.description || `共 ${parsed.chapters.length} 章`,
          totalChapters: parsed.chapters.length,
          chapters: parsed.chapters,
        };

        let authorProfile: AuthorProfile = {
          id: authorId,
          name: parsed.author,
          biography: `${parsed.author}是一位作家，著有《${parsed.title}》。`,
          personality: '',
          writingStyle: '',
          keyConcepts: [],
          timeline: [],
          works: [
            {
              title: `《${parsed.title}》`,
              year: '近年',
              description: '代表作',
              type: 'book',
            },
          ],
        };

        // Try to generate enriched profile with AI
        const kimiApiKey = import.meta.env.VITE_KIMI_API_KEY;
        console.log('[Import] Kimi API key exists:', !!kimiApiKey);

        if (kimiApiKey) {
          try {
            setEnrichingAuthor(true);
            setImportProgress('正在联网搜索作者信息，打磨数字人...');
            console.log('[Import] Starting AI author profile generation...');

            const enriched = await generateAuthorProfile(
              parsed.author,
              parsed.title,
              parsed.description,
              parsed.chapters,
              kimiApiKey
            );

            console.log('[Import] AI generation completed');
            console.log('[Import] Enriched biography length:', enriched.biography?.length || 0);
            console.log('[Import] Enriched personality length:', enriched.personality?.length || 0);
            console.log('[Import] Enriched writingStyle length:', enriched.writingStyle?.length || 0);
            console.log('[Import] Enriched keyConcepts count:', enriched.keyConcepts?.length || 0);
            console.log('[Import] Enriched timeline count:', enriched.timeline?.length || 0);
            console.log('[Import] Enriched works count:', enriched.works?.length || 0);

            // Only use enriched data if it's actually filled
            if (enriched.biography && enriched.biography.length > 50) {
              authorProfile = {
                ...enriched,
                id: authorId,
                name: parsed.author,
              };
              console.log('[Import] Using enriched profile');
            } else {
              console.warn('[Import] Enriched profile too short, using fallback');
            }
          } catch (error) {
            console.error('[Import] Author enrichment failed:', error);
            setImportProgress('AI生成失败，使用默认档案...');
            // Keep the fallback profile
          } finally {
            setEnrichingAuthor(false);
          }
        } else {
          console.warn('[Import] No Kimi API key found');
        }

        console.log('[Import] Final author profile:', {
          biography: authorProfile.biography?.slice(0, 100),
          personality: authorProfile.personality?.slice(0, 100),
          writingStyle: authorProfile.writingStyle?.slice(0, 100),
          keyConcepts: authorProfile.keyConcepts?.length,
          timeline: authorProfile.timeline?.length,
          works: authorProfile.works?.length,
        });

        addBook(book, authorProfile);

        setImportProgress('导入成功！');
        setTimeout(() => {
          setIsImporting(false);
          setImportProgress('');
          navigate(`/read/${bookId}`);
        }, 500);
      } catch (error) {
        console.error('Import error:', error);
        setImportError(
          error instanceof Error ? error.message : '导入失败，请检查文件格式'
        );
        setIsImporting(false);
        setEnrichingAuthor(false);
      }

      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    },
    [navigate, addBook]
  );

  // Show loading state while initializing
  if (isLoading || !isInitialized) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-center">
          <Loader2 size={32} className="text-[var(--accent)] animate-spin mx-auto mb-4" />
          <p className="text-sm text-[var(--text-muted)]">正在加载...</p>
        </div>
      </div>
    );
  }

  // Show auth screen if no user
  if (!user) {
    return <UserAuth />;
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      {/* Header */}
      <header className="border-b border-[var(--border)] bg-[var(--bg-secondary)]">
        <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-[var(--accent)] flex items-center justify-center">
              <Library size={22} className="text-[var(--bg-primary)]" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-[var(--text-primary)]">
                与作者对话
              </h1>
              <p className="text-xs text-[var(--text-muted)]">
                沉浸式阅读平台 · 选中段落与作者数字人交流
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={isImporting}
              className="flex items-center gap-2 px-4 py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] rounded-xl font-medium hover:bg-[var(--accent-hover)] transition-colors disabled:opacity-50"
            >
              {isImporting ? (
                <Loader2 size={18} className="animate-spin" />
              ) : (
                <Upload size={18} />
              )}
              {isImporting ? '导入中...' : '导入书籍'}
            </button>
            <UserAuth />
          </div>
        </div>
      </header>

      <input
        ref={fileInputRef}
        type="file"
        accept=".epub,.txt"
        onChange={handleFileSelect}
        className="hidden"
      />

      {/* Import Progress / Error */}
      {(importProgress || importError) && (
        <div className="max-w-6xl mx-auto px-6 mt-4">
          {importError && (
            <div className="flex items-center gap-2 p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-400">
              <AlertCircle size={18} />
              <span className="text-sm">{importError}</span>
              <button
                onClick={() => setImportError('')}
                className="ml-auto hover:text-red-300"
              >
                <X size={16} />
              </button>
            </div>
          )}
          {importProgress && !importError && (
            <div className="flex items-center gap-2 p-4 bg-[var(--accent)]/10 border border-[var(--accent)]/30 rounded-xl text-[var(--accent)]">
              <Loader2 size={18} className="animate-spin" />
              <span className="text-sm">{importProgress}</span>
              {enrichingAuthor && (
                <Sparkles size={14} className="animate-pulse" />
              )}
            </div>
          )}
        </div>
      )}

      {/* Books Grid */}
      <main className="max-w-6xl mx-auto px-6 py-8">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">
            我的书架
          </h2>
          <span className="text-sm text-[var(--text-muted)]">
            共 {books.length} 本书
          </span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {books.map((book) => (
            <BookCard
              key={book.id}
              book={book}
              onClick={() => handleBookClick(book.id)}
              onDelete={(e) => handleDeleteBook(e, book.id)}
            />
          ))}

          {/* Import Card */}
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="group relative flex flex-col items-center justify-center gap-3 p-6 rounded-2xl border-2 border-dashed border-[var(--border)] hover:border-[var(--accent)] hover:bg-[var(--accent)]/5 transition-all min-h-[240px] disabled:opacity-50"
          >
            <div className="w-14 h-14 rounded-2xl bg-[var(--bg-tertiary)] group-hover:bg-[var(--accent)]/20 flex items-center justify-center transition-colors">
              <Upload
                size={28}
                className="text-[var(--text-muted)] group-hover:text-[var(--accent)] transition-colors"
              />
            </div>
            <div className="text-center">
              <p className="text-sm font-medium text-[var(--text-secondary)] group-hover:text-[var(--text-primary)]">
                导入新书
              </p>
              <p className="text-xs text-[var(--text-muted)] mt-1">
                支持 .epub 和 .txt 格式
              </p>
            </div>
          </button>
        </div>

        {/* Import Guide */}
        <div className="mt-12 p-6 rounded-2xl bg-[var(--bg-secondary)] border border-[var(--border)]">
          <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-4 flex items-center gap-2">
            <FileText size={16} className="text-[var(--accent)]" />
            导入指南
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="p-4 rounded-xl bg-[var(--bg-tertiary)]">
              <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/20 flex items-center justify-center mb-3">
                <span className="text-sm font-bold text-[var(--accent)]">1</span>
              </div>
              <p className="text-sm font-medium text-[var(--text-secondary)] mb-1">
                选择文件
              </p>
              <p className="text-xs text-[var(--text-muted)]">
                支持 EPUB 电子书格式或纯文本 TXT 格式
              </p>
            </div>
            <div className="p-4 rounded-xl bg-[var(--bg-tertiary)]">
              <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/20 flex items-center justify-center mb-3">
                <span className="text-sm font-bold text-[var(--accent)]">2</span>
              </div>
              <p className="text-sm font-medium text-[var(--text-secondary)] mb-1">
                自动解析
              </p>
              <p className="text-xs text-[var(--text-muted)]">
                系统自动提取章节结构、书名和作者信息
              </p>
            </div>
            <div className="p-4 rounded-xl bg-[var(--bg-tertiary)]">
              <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/20 flex items-center justify-center mb-3">
                <span className="text-sm font-bold text-[var(--accent)]">3</span>
              </div>
              <p className="text-sm font-medium text-[var(--text-secondary)] mb-1">
                生成数字人
              </p>
              <p className="text-xs text-[var(--text-muted)]">
                联网搜索作者信息，自动生成饱满的数字人档案
              </p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

function BookCard({
  book,
  onClick,
  onDelete,
}: {
  book: Book;
  onClick: () => void;
  onDelete: (e: React.MouseEvent) => void;
}) {
  return (
    <button
      onClick={onClick}
      className="group relative flex flex-col p-5 rounded-2xl bg-[var(--bg-secondary)] border border-[var(--border)] hover:border-[var(--accent)] hover:shadow-lg hover:shadow-[var(--accent)]/5 transition-all text-left"
    >
      <div className="flex items-start justify-between mb-3">
        <div className="w-12 h-12 rounded-xl bg-[var(--accent)]/15 flex items-center justify-center flex-shrink-0">
          <BookOpen size={24} className="text-[var(--accent)]" />
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={onDelete}
            className="p-1.5 text-[var(--text-muted)] hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
            title="删除"
          >
            <Trash2 size={14} />
          </button>
          <ChevronRight
            size={18}
            className="text-[var(--text-muted)] group-hover:text-[var(--accent)] group-hover:translate-x-0.5 transition-all"
          />
        </div>
      </div>

      <h3 className="text-base font-semibold text-[var(--text-primary)] mb-1 line-clamp-2">
        {book.title}
      </h3>

      <div className="flex items-center gap-1.5 text-sm text-[var(--text-muted)] mb-3">
        <User size={14} />
        <span className="line-clamp-1">{book.author}</span>
      </div>

      <p className="text-xs text-[var(--text-muted)] line-clamp-2 mb-3 flex-1">
        {book.description}
      </p>

      <div className="flex items-center justify-between pt-3 border-t border-[var(--border)]">
        <span className="text-xs text-[var(--text-muted)]">
          {book.totalChapters} 章
        </span>
        <span className="text-xs font-medium text-[var(--accent)]">
          开始阅读
        </span>
      </div>
    </button>
  );
}
