import { useState } from 'react';
import { useUserStore } from '@/store/useUserStore';
import { User, LogOut, Users, Plus, X, ChevronDown } from 'lucide-react';

export function UserAuth() {
  const { user, createUser, logout, switchToUser, getAllUsersList } = useUserStore();
  const [showCreate, setShowCreate] = useState(false);
  const [showSwitch, setShowSwitch] = useState(false);
  const [username, setUsername] = useState('');
  const [displayName, setDisplayName] = useState('');

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (username.trim() && displayName.trim()) {
      createUser(username.trim(), displayName.trim());
      setShowCreate(false);
      setUsername('');
      setDisplayName('');
    }
  };

  if (!user) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[var(--bg-primary)]">
        <div className="w-full max-w-md mx-4">
          <div className="text-center mb-8">
            <div className="w-16 h-16 rounded-2xl bg-[var(--accent)] flex items-center justify-center mx-auto mb-4">
              <User size={32} className="text-[var(--bg-primary)]" />
            </div>
            <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">
              与作者对话
            </h1>
            <p className="text-sm text-[var(--text-muted)]">
              沉浸式阅读平台 · 选中段落与作者数字人交流
            </p>
          </div>

          <div className="bg-[var(--bg-secondary)] rounded-2xl border border-[var(--border)] p-6">
            <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-4">
              开始使用
            </h2>

            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1.5">
                  用户名
                </label>
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="请输入用户名"
                  className="w-full bg-[var(--bg-tertiary)] text-[var(--text-primary)] placeholder:text-[var(--text-muted)] px-4 py-2.5 rounded-xl text-sm outline-none focus:ring-1 focus:ring-[var(--accent)]"
                  required
                />
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1.5">
                  显示名称
                </label>
                <input
                  type="text"
                  value={displayName}
                  onChange={(e) => setDisplayName(e.target.value)}
                  placeholder="请输入显示名称"
                  className="w-full bg-[var(--bg-tertiary)] text-[var(--text-primary)] placeholder:text-[var(--text-muted)] px-4 py-2.5 rounded-xl text-sm outline-none focus:ring-1 focus:ring-[var(--accent)]"
                  required
                />
              </div>
              <button
                type="submit"
                className="w-full py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] rounded-xl font-medium hover:bg-[var(--accent-hover)] transition-colors"
              >
                创建账号
              </button>
            </form>

            {getAllUsersList().length > 0 && (
              <div className="mt-4 pt-4 border-t border-[var(--border)]">
                <p className="text-xs text-[var(--text-muted)] mb-2">已有账号：</p>
                <div className="space-y-1">
                  {getAllUsersList().map((u) => (
                    <button
                      key={u.id}
                      onClick={() => switchToUser(u.id)}
                      className="w-full text-left px-3 py-2 rounded-lg text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] hover:text-[var(--text-primary)] transition-colors flex items-center gap-2"
                    >
                      <User size={14} />
                      {u.displayName}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="relative">
      <button
        onClick={() => setShowSwitch(!showSwitch)}
        className="flex items-center gap-2 px-3 py-2 rounded-xl bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-colors"
      >
        <div className="w-7 h-7 rounded-full bg-[var(--accent)]/20 flex items-center justify-center">
          <User size={14} className="text-[var(--accent)]" />
        </div>
        <span className="text-sm font-medium">{user.displayName}</span>
        <ChevronDown size={14} />
      </button>

      {showSwitch && (
        <>
          <div
            className="fixed inset-0 z-40"
            onClick={() => setShowSwitch(false)}
          />
          <div className="absolute right-0 top-full mt-2 w-56 bg-[var(--bg-secondary)] border border-[var(--border)] rounded-xl shadow-xl z-50 py-2">
            <div className="px-3 py-2 border-b border-[var(--border)]">
              <p className="text-xs text-[var(--text-muted)]">当前用户</p>
              <p className="text-sm font-medium text-[var(--text-primary)]">
                {user.displayName}
              </p>
            </div>

            {getAllUsersList().filter((u) => u.id !== user.id).length > 0 && (
              <div className="py-1">
                <p className="px-3 py-1 text-xs text-[var(--text-muted)]">切换账号</p>
                {getAllUsersList()
                  .filter((u) => u.id !== user.id)
                  .map((u) => (
                    <button
                      key={u.id}
                      onClick={() => {
                        switchToUser(u.id);
                        setShowSwitch(false);
                        window.location.reload();
                      }}
                      className="w-full text-left px-3 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] hover:text-[var(--text-primary)] transition-colors flex items-center gap-2"
                    >
                      <Users size={14} />
                      {u.displayName}
                    </button>
                  ))}
              </div>
            )}

            <div className="border-t border-[var(--border)] py-1">
              <button
                onClick={() => {
                  setShowCreate(true);
                  setShowSwitch(false);
                }}
                className="w-full text-left px-3 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] hover:text-[var(--text-primary)] transition-colors flex items-center gap-2"
              >
                <Plus size={14} />
                创建新账号
              </button>
              <button
                onClick={() => {
                  logout();
                  setShowSwitch(false);
                  window.location.reload();
                }}
                className="w-full text-left px-3 py-2 text-sm text-red-400 hover:bg-red-500/10 transition-colors flex items-center gap-2"
              >
                <LogOut size={14} />
                退出登录
              </button>
            </div>
          </div>
        </>
      )}

      {showCreate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-[var(--bg-secondary)] rounded-2xl w-full max-w-sm mx-4 p-6 border border-[var(--border)]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-[var(--text-primary)]">
                创建新账号
              </h3>
              <button
                onClick={() => setShowCreate(false)}
                className="p-1 text-[var(--text-muted)] hover:text-[var(--text-primary)]"
              >
                <X size={18} />
              </button>
            </div>
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1.5">
                  用户名
                </label>
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="请输入用户名"
                  className="w-full bg-[var(--bg-tertiary)] text-[var(--text-primary)] placeholder:text-[var(--text-muted)] px-4 py-2.5 rounded-xl text-sm outline-none focus:ring-1 focus:ring-[var(--accent)]"
                  required
                />
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1.5">
                  显示名称
                </label>
                <input
                  type="text"
                  value={displayName}
                  onChange={(e) => setDisplayName(e.target.value)}
                  placeholder="请输入显示名称"
                  className="w-full bg-[var(--bg-tertiary)] text-[var(--text-primary)] placeholder:text-[var(--text-muted)] px-4 py-2.5 rounded-xl text-sm outline-none focus:ring-1 focus:ring-[var(--accent)]"
                  required
                />
              </div>
              <button
                type="submit"
                className="w-full py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] rounded-xl font-medium hover:bg-[var(--accent-hover)] transition-colors"
              >
                创建
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
