import { useState, useRef, useEffect } from 'react';
import { useReaderStore } from '@/store/useReaderStore';
import { useUserStore } from '@/store/useUserStore';
import { sendMessageToAI } from '@/services/aiService';
import { X, Send, User, Bot, Sparkles, History } from 'lucide-react';

interface ChatPanelProps {
  bookId: string;
}

export function ChatPanel({ bookId }: ChatPanelProps) {
  const { isChatOpen, toggleChat, selectedText, chatMessages, addMessage, isLoading, setIsLoading, currentChapter } = useReaderStore();
  const { user, userData, getAuthorProfile, saveConversation, getConversation } = useUserStore();
  const [inputValue, setInputValue] = useState('');
  const [showHistory, setShowHistory] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const book = userData?.books.find((b) => b.id === bookId);
  const authorProfile = getAuthorProfile(bookId);

  // Load conversation history when opening chat
  useEffect(() => {
    if (user && isChatOpen) {
      const savedMessages = getConversation(bookId);
      if (savedMessages.length > 0 && chatMessages.length === 0) {
        savedMessages.forEach((msg) => addMessage(msg));
      }
    }
  }, [user, isChatOpen, bookId, getConversation, addMessage, chatMessages.length]);

  // Save conversation when messages change
  useEffect(() => {
    if (user && chatMessages.length > 0) {
      saveConversation(bookId, chatMessages);
    }
  }, [user, chatMessages, bookId, saveConversation]);

  const quickQuestions = [
    '这段话的核心思想是什么？',
    '为什么要这样写？',
    '当时的背景是怎样的？',
    '这与我其他著作有什么联系？',
  ];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatMessages]);

  useEffect(() => {
    if (isChatOpen) {
      inputRef.current?.focus();
    }
  }, [isChatOpen]);

  const handleSend = async (content: string) => {
    if (!content.trim() || isLoading) return;

    const userMessage = {
      id: Date.now().toString(),
      role: 'user' as const,
      content: content.trim(),
      timestamp: Date.now(),
      selectedText,
      chapterId: currentChapter?.id,
    };

    addMessage(userMessage);
    setInputValue('');
    setIsLoading(true);

    try {
      const response = await sendMessageToAI({
        message: content.trim(),
        selectedText,
        chapterTitle: currentChapter?.title || '',
        bookTitle: book?.title || '',
        authorName: book?.author || '',
        bookId: bookId,
        history: chatMessages.map((msg) => ({
          role: msg.role,
          content: msg.content,
        })),
      });

      const assistantMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant' as const,
        content: response,
        timestamp: Date.now(),
        selectedText,
        chapterId: currentChapter?.id,
      };

      addMessage(assistantMessage);
    } catch (error) {
      const errorMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant' as const,
        content: '抱歉，我暂时无法回答这个问题。请稍后再试。',
        timestamp: Date.now(),
        selectedText,
        chapterId: currentChapter?.id,
      };

      addMessage(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isChatOpen) return null;

  return (
    <div className="fixed right-0 top-0 h-full w-96 bg-[var(--bg-secondary)] border-l border-[var(--border)] flex flex-col z-40 shadow-2xl">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-[var(--border)]">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-[var(--accent)]/20 flex items-center justify-center">
            <Sparkles size={16} className="text-[var(--accent)]" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-[var(--text-primary)]">
              与作者对话
            </h3>
            <p className="text-xs text-[var(--text-muted)]">
              {book?.author || '作者数字人'}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={() => setShowHistory(!showHistory)}
            className={`p-1.5 rounded-lg transition-colors ${
              showHistory
                ? 'text-[var(--accent)] bg-[var(--accent)]/10'
                : 'text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)]'
            }`}
            title="历史记录"
          >
            <History size={16} />
          </button>
          <button
            onClick={() => toggleChat(false)}
            className="p-1.5 text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] rounded-lg transition-colors"
          >
            <X size={18} />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {chatMessages.length === 0 && (
          <div className="text-center py-8">
            <div className="w-12 h-12 rounded-full bg-[var(--accent)]/10 flex items-center justify-center mx-auto mb-3">
              <Sparkles size={20} className="text-[var(--accent)]" />
            </div>
            <p className="text-sm text-[var(--text-secondary)] mb-1">
              选中段落，向作者提问
            </p>
            <p className="text-xs text-[var(--text-muted)]">
              作者数字人会以本人的口吻回答你
            </p>

            {selectedText && (
              <div className="mt-4 p-3 bg-[var(--bg-tertiary)] rounded-lg text-left">
                <p className="text-xs text-[var(--text-muted)] mb-1">已选中：</p>
                <p className="text-sm text-[var(--text-secondary)] line-clamp-3">
                  {selectedText}
                </p>
              </div>
            )}

            <div className="mt-4 space-y-2">
              {quickQuestions.map((q, i) => (
                <button
                  key={i}
                  onClick={() => handleSend(q)}
                  className="block w-full text-left px-3 py-2 text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] rounded-lg transition-colors"
                >
                  {q}
                </button>
              ))}
            </div>
          </div>
        )}

        {chatMessages.map((msg) => (
          <div
            key={msg.id}
            className={`flex gap-2 ${
              msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
            }`}
          >
            <div
              className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 ${
                msg.role === 'user'
                  ? 'bg-[var(--bg-tertiary)]'
                  : 'bg-[var(--accent)]/20'
              }`}
            >
              {msg.role === 'user' ? (
                <User size={14} className="text-[var(--text-secondary)]" />
              ) : (
                <Bot size={14} className="text-[var(--accent)]" />
              )}
            </div>
            <div
              className={`max-w-[80%] px-3 py-2 rounded-2xl text-sm leading-relaxed ${
                msg.role === 'user'
                  ? 'bg-[var(--accent)] text-[var(--bg-primary)] rounded-tr-sm'
                  : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded-tl-sm'
              }`}
            >
              {msg.content}
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex gap-2">
            <div className="w-7 h-7 rounded-full bg-[var(--accent)]/20 flex items-center justify-center flex-shrink-0">
              <Bot size={14} className="text-[var(--accent)]" />
            </div>
            <div className="bg-[var(--bg-tertiary)] px-3 py-2 rounded-2xl rounded-tl-sm">
              <div className="flex gap-1">
                <div className="w-2 h-2 rounded-full bg-[var(--text-muted)] animate-bounce" style={{ animationDelay: '0ms' }} />
                <div className="w-2 h-2 rounded-full bg-[var(--text-muted)] animate-bounce" style={{ animationDelay: '150ms' }} />
                <div className="w-2 h-2 rounded-full bg-[var(--text-muted)] animate-bounce" style={{ animationDelay: '300ms' }} />
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-[var(--border)]">
        <div className="flex gap-2">
          <input
            ref={inputRef}
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSend(inputValue);
              }
            }}
            placeholder="向作者提问..."
            className="flex-1 bg-[var(--bg-tertiary)] text-[var(--text-primary)] placeholder:text-[var(--text-muted)] px-3 py-2 rounded-xl text-sm outline-none focus:ring-1 focus:ring-[var(--accent)]"
          />
          <button
            onClick={() => handleSend(inputValue)}
            disabled={!inputValue.trim() || isLoading}
            className="p-2 bg-[var(--accent)] text-[var(--bg-primary)] rounded-xl hover:bg-[var(--accent-hover)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}
