import type { Book, AuthorProfile } from '@/types';
import { sampleBook } from './bookData';
import { maoZedongProfile } from './authorProfile';
import { getCurrentUserData, addBookToUser } from '@/services/userStorage';

export interface BookEntry {
  book: Book;
  authorProfile: AuthorProfile;
}

// Default books that are always available
const defaultBooks: BookEntry[] = [
  {
    book: sampleBook,
    authorProfile: maoZedongProfile,
  },
];

export function getBooksForUser(): Book[] {
  const userData = getCurrentUserData();
  if (userData && userData.books.length > 0) {
    return userData.books;
  }
  // If no user data, return default books
  return defaultBooks.map((entry) => entry.book);
}

export function getAuthorProfileForUser(bookId: string): AuthorProfile | undefined {
  const userData = getCurrentUserData();
  if (userData) {
    const book = userData.books.find((b) => b.id === bookId);
    if (book) {
      return userData.authorProfiles.find((p) => p.id === book.authorId);
    }
  }
  // Fallback to default
  const defaultEntry = defaultBooks.find((entry) => entry.book.id === bookId);
  return defaultEntry?.authorProfile;
}

export function getBookForUser(bookId: string): Book | undefined {
  const userData = getCurrentUserData();
  if (userData) {
    return userData.books.find((b) => b.id === bookId);
  }
  const defaultEntry = defaultBooks.find((entry) => entry.book.id === bookId);
  return defaultEntry?.book;
}

export function registerBook(book: Book, authorProfile: AuthorProfile) {
  const userData = getCurrentUserData();
  if (userData) {
    addBookToUser(userData.user.id, book, authorProfile);
  }
}

export function getAllBooksForUser(): Book[] {
  return getBooksForUser();
}

export function hasBookForUser(bookId: string): boolean {
  const books = getBooksForUser();
  return books.some((b) => b.id === bookId);
}

// Legacy exports for backward compatibility
export function getBookEntry(bookId: string): BookEntry | undefined {
  const book = getBookForUser(bookId);
  const profile = getAuthorProfileForUser(bookId);
  if (book && profile) {
    return { book, authorProfile: profile };
  }
  return defaultBooks.find((entry) => entry.book.id === bookId);
}

export function getBook(bookId: string): Book | undefined {
  return getBookForUser(bookId);
}

export function getAuthorProfile(bookId: string): AuthorProfile | undefined {
  return getAuthorProfileForUser(bookId);
}

export function getAllBooks(): Book[] {
  return getAllBooksForUser();
}

export function removeBook(bookId: string) {
  const userData = getCurrentUserData();
  if (userData) {
    const { removeBookFromUser } = require('@/services/userStorage');
    removeBookFromUser(userData.user.id, bookId);
  }
}

export function hasBook(bookId: string): boolean {
  return hasBookForUser(bookId);
}
