import { create } from 'zustand';
import type { User, UserData, Book, AuthorProfile, Highlight, Message } from '@/types';
import {
  getCurrentUser,
  getCurrentUserData,
  createUser as createUserService,
  logout as logoutService,
  addBookToUser,
  removeBookFromUser,
  addHighlight as addHighlightService,
  removeHighlight as removeHighlightService,
  getHighlights as getHighlightsService,
  saveConversation as saveConversationService,
  getConversation as getConversationService,
  setLastReadBook,
  getAllUsers,
  switchUser,
  loadUserData,
} from '@/services/userStorage';

interface UserState {
  user: User | null;
  userData: UserData | null;
  isLoading: boolean;
  isInitialized: boolean;

  init: () => void;
  createUser: (username: string, displayName: string) => void;
  logout: () => void;
  switchToUser: (userId: string) => boolean;
  getAllUsersList: () => User[];

  addBook: (book: Book, authorProfile: AuthorProfile) => void;
  removeBook: (bookId: string) => void;
  getBooks: () => Book[];
  getAuthorProfile: (bookId: string) => AuthorProfile | undefined;

  addHighlight: (highlight: Highlight) => void;
  removeHighlight: (highlightId: string) => void;
  getHighlights: (bookId?: string) => Highlight[];

  saveConversation: (bookId: string, messages: Message[]) => void;
  getConversation: (bookId: string) => Message[];

  setLastReadBookId: (bookId: string) => void;
  getLastReadBookId: () => string | undefined;

  refreshUserData: () => void;
}

export const useUserStore = create<UserState>((set, get) => ({
  user: null,
  userData: null,
  isLoading: true,
  isInitialized: false,

  init: () => {
    const state = get();
    if (state.isInitialized) return;

    try {
      const user = getCurrentUser();
      const userData = getCurrentUserData();
      set({ user, userData, isLoading: false, isInitialized: true });
    } catch (e) {
      console.error('Failed to initialize user store:', e);
      set({ user: null, userData: null, isLoading: false, isInitialized: true });
    }
  },

  createUser: (username, displayName) => {
    try {
      const user = createUserService(username, displayName);
      const userData = getCurrentUserData();
      set({ user, userData, isInitialized: true });
    } catch (e) {
      console.error('Failed to create user:', e);
    }
  },

  logout: () => {
    logoutService();
    set({ user: null, userData: null, isInitialized: true });
  },

  switchToUser: (userId) => {
    try {
      const success = switchUser(userId);
      if (success) {
        const user = getCurrentUser();
        const userData = getCurrentUserData();
        set({ user, userData });
      }
      return success;
    } catch (e) {
      console.error('Failed to switch user:', e);
      return false;
    }
  },

  getAllUsersList: () => {
    try {
      return getAllUsers();
    } catch (e) {
      console.error('Failed to get users:', e);
      return [];
    }
  },

  addBook: (book, authorProfile) => {
    const { user } = get();
    if (!user) return;

    try {
      addBookToUser(user.id, book, authorProfile);
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to add book:', e);
    }
  },

  removeBook: (bookId) => {
    const { user } = get();
    if (!user) return;

    try {
      removeBookFromUser(user.id, bookId);
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to remove book:', e);
    }
  },

  getBooks: () => {
    const { userData } = get();
    return userData?.books || [];
  },

  getAuthorProfile: (bookId) => {
    const { userData } = get();
    if (!userData) return undefined;

    const book = userData.books.find((b) => b.id === bookId);
    if (!book) return undefined;

    return userData.authorProfiles.find((p) => p.id === book.authorId);
  },

  addHighlight: (highlight) => {
    const { user } = get();
    if (!user) return;

    try {
      addHighlightService(user.id, highlight);
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to add highlight:', e);
    }
  },

  removeHighlight: (highlightId) => {
    const { user } = get();
    if (!user) return;

    try {
      removeHighlightService(user.id, highlightId);
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to remove highlight:', e);
    }
  },

  getHighlights: (bookId) => {
    const { user } = get();
    if (!user) return [];

    try {
      return getHighlightsService(user.id, bookId);
    } catch (e) {
      console.error('Failed to get highlights:', e);
      return [];
    }
  },

  saveConversation: (bookId, messages) => {
    const { user } = get();
    if (!user) return;

    try {
      saveConversationService(user.id, bookId, messages);
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to save conversation:', e);
    }
  },

  getConversation: (bookId) => {
    const { user } = get();
    if (!user) return [];

    try {
      return getConversationService(user.id, bookId);
    } catch (e) {
      console.error('Failed to get conversation:', e);
      return [];
    }
  },

  setLastReadBookId: (bookId) => {
    const { user } = get();
    if (!user) return;

    try {
      setLastReadBook(user.id, bookId);
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to set last read book:', e);
    }
  },

  getLastReadBookId: () => {
    const { userData } = get();
    return userData?.lastReadBookId;
  },

  refreshUserData: () => {
    try {
      const userData = getCurrentUserData();
      set({ userData });
    } catch (e) {
      console.error('Failed to refresh user data:', e);
    }
  },
}));
