import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Sidebar } from '@/components/Sidebar';
import { TextContent } from '@/components/TextContent';
import { ChatPanel } from '@/components/ChatPanel';
import { AuthorProfilePanel } from '@/components/AuthorProfile';
import { SearchPanel } from '@/components/SearchPanel';
import { UserAuth } from '@/components/UserAuth';
import { useUserStore } from '@/store/useUserStore';
import { useReaderStore } from '@/store/useReaderStore';
import { MessageCircle, User, Search, BookOpen, Loader2 } from 'lucide-react';
import type { Chapter, Book, AuthorProfile } from '@/types';

export function ReaderPage() {
  const { bookId } = useParams<{ bookId: string }>();
  const navigate = useNavigate();
  const { user, userData, isLoading, isInitialized, init } = useUserStore();
  const [currentChapterId, setCurrentChapterId] = useState('');
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const { isChatOpen, toggleChat, setCurrentChapter, clearChat } = useReaderStore();

  // Refs to avoid stale closures and infinite loops
  const hasInitChapterRef = useRef(false);

  // Initialize user store once
  useEffect(() => {
    if (!isInitialized) {
      init();
    }
  }, [init, isInitialized]);

  // Find book from user data - simple lookup, no useMemo
  const book: Book | undefined = bookId && userData?.books
    ? userData.books.find((b) => b.id === bookId)
    : undefined;

  // Find author profile
  const authorProfile: AuthorProfile | undefined = book && userData?.authorProfiles
    ? userData.authorProfiles.find((p) => p.id === book.authorId)
    : undefined;

  // Set initial chapter when book is loaded - only once per book
  useEffect(() => {
    if (book && book.chapters && book.chapters.length > 0 && !hasInitChapterRef.current) {
      hasInitChapterRef.current = true;
      const firstChapter = book.chapters[0];
      setCurrentChapterId(firstChapter.id);
      setCurrentChapter(firstChapter);
      clearChat();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [book?.id]); // Only depend on book.id, not the whole book object

  // Reset init ref when bookId changes
  useEffect(() => {
    hasInitChapterRef.current = false;
  }, [bookId]);

  const currentChapter = book?.chapters
    ? book.chapters.find((ch) => ch.id === currentChapterId) || book.chapters[0]
    : undefined;

  const handleChapterSelect = (chapter: Chapter) => {
    setCurrentChapterId(chapter.id);
    setCurrentChapter(chapter);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setIsSearchOpen((prev) => !prev);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Show loading state while initializing
  if (isLoading || !isInitialized) {
    return (
      <div className="flex h-screen bg-[var(--bg-primary)] items-center justify-center">
        <div className="text-center">
          <Loader2 size={32} className="text-[var(--accent)] animate-spin mx-auto mb-4" />
          <p className="text-sm text-[var(--text-muted)]">正在加载...</p>
        </div>
      </div>
    );
  }

  // Show auth screen if no user
  if (!user) {
    return <UserAuth />;
  }

  // Show not found if book doesn't exist
  if (!book) {
    return (
      <div className="flex h-screen bg-[var(--bg-primary)] items-center justify-center">
        <div className="text-center">
          <BookOpen size={48} className="text-[var(--text-muted)] mx-auto mb-4" />
          <p className="text-[var(--text-secondary)] mb-4">书籍未找到</p>
          <button
            onClick={() => navigate('/')}
            className="px-4 py-2 bg-[var(--accent)] text-[var(--bg-primary)] rounded-lg hover:bg-[var(--accent-hover)] transition-colors"
          >
            返回书架
          </button>
        </div>
      </div>
    );
  }

  // Show error if book has no chapters
  if (!book.chapters || book.chapters.length === 0) {
    return (
      <div className="flex h-screen bg-[var(--bg-primary)] items-center justify-center">
        <div className="text-center">
          <BookOpen size={48} className="text-[var(--text-muted)] mx-auto mb-4" />
          <p className="text-[var(--text-secondary)] mb-4">这本书没有可读内容</p>
          <button
            onClick={() => navigate('/')}
            className="px-4 py-2 bg-[var(--accent)] text-[var(--bg-primary)] rounded-lg hover:bg-[var(--accent-hover)] transition-colors"
          >
            返回书架
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-[var(--bg-primary)] overflow-hidden">
      <Sidebar
        chapters={book.chapters}
        currentChapterId={currentChapterId}
        onChapterSelect={handleChapterSelect}
        authorName={book.author}
        bookTitle={book.title}
        onBack={() => navigate('/')}
      />

      <TextContent chapter={currentChapter} bookId={book.id} />

      {isChatOpen && <ChatPanel bookId={book.id} />}

      {!isChatOpen && (
        <button
          onClick={() => toggleChat(true)}
          className="fixed right-6 bottom-6 w-12 h-12 bg-[var(--accent)] text-[var(--bg-primary)] rounded-full shadow-lg flex items-center justify-center hover:bg-[var(--accent-hover)] transition-colors z-50"
          title="与作者对话"
        >
          <MessageCircle size={20} />
        </button>
      )}

      <button
        onClick={() => setIsProfileOpen(true)}
        className="fixed right-6 bottom-20 w-10 h-10 bg-[var(--bg-tertiary)] text-[var(--text-secondary)] rounded-full shadow-lg flex items-center justify-center hover:bg-[var(--border)] hover:text-[var(--text-primary)] transition-colors z-50 border border-[var(--border)]"
        title="作者档案"
      >
        <User size={18} />
      </button>

      <button
        onClick={() => setIsSearchOpen(true)}
        className="fixed right-6 bottom-[7.5rem] w-10 h-10 bg-[var(--bg-tertiary)] text-[var(--text-secondary)] rounded-full shadow-lg flex items-center justify-center hover:bg-[var(--border)] hover:text-[var(--text-primary)] transition-colors z-50 border border-[var(--border)]"
        title="搜索 (Ctrl+K)"
      >
        <Search size={18} />
      </button>

      {authorProfile && (
        <AuthorProfilePanel
          isOpen={isProfileOpen}
          onClose={() => setIsProfileOpen(false)}
          profile={authorProfile}
        />
      )}

      <SearchPanel
        isOpen={isSearchOpen}
        onClose={() => setIsSearchOpen(false)}
        onChapterSelect={handleChapterSelect}
        chapters={book.chapters}
      />
    </div>
  );
}
